public static class H {
  [DllImport("ntdll.dll")] static extern int NtQuerySystemInformation(int c, IntPtr b, int l, out int r);
  [DllImport("ntdll.dll")] static extern int NtQueryObject(IntPtr h, int c, IntPtr b, int l, out int r);
  [DllImport("kernel32.dll")] static extern IntPtr OpenProcess(int a, bool i, int p);
  [DllImport("kernel32.dll")] static extern bool DuplicateHandle(IntPtr sp, IntPtr sh, IntPtr tp, out IntPtr th, int a, bool i, int o);
  [DllImport("kernel32.dll")] static extern IntPtr GetCurrentProcess();
  [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
  [DllImport("kernel32.dll")] static extern int GetFileType(IntPtr h);
  static string Q(IntPtr h, int cls) { int r; IntPtr b = Marshal.AllocHGlobal(0x2000); try { if (NtQueryObject(h, cls, b, 0x2000, out r) != 0) return null; var len = Marshal.ReadInt16(b); var p = Marshal.ReadIntPtr(b, IntPtr.Size); if (cls==2) { len = Marshal.ReadInt16(b); p = Marshal.ReadIntPtr(b, IntPtr.Size);} return len > 0 ? Marshal.PtrToStringUni(p, len/2) : ""; } finally { Marshal.FreeHGlobal(b); } }
  public static List<string> Dump(int pid) {
    var res = new List<string>(); int size = 1<<24, r; IntPtr buf = Marshal.AllocHGlobal(size);
    int st = NtQuerySystemInformation(64, buf, size, out r); if (st != 0) { res.Add("NtQSI status " + st.ToString("X")); return res; }
    long n = Marshal.ReadInt64(buf); int esz = 8*3 + 4*2 + 2*2 + 8 - 8 + 8; esz = 40; 
    IntPtr hp = OpenProcess(0x40, false, pid);
    for (long i = 0; i < n; i++) {
      IntPtr e = new IntPtr(buf.ToInt64() + 16 + i*esz);
      long upid = Marshal.ReadInt64(e, 8); if (upid != pid) continue;
      long hv = Marshal.ReadInt64(e, 16);
      IntPtr d; if (!DuplicateHandle(hp, new IntPtr(hv), GetCurrentProcess(), out d, 0, false, 2)) continue;
      string type = Q(d, 2); string name = null; int ft = -1;
      if (type == "File") { ft = GetFileType(d); if (ft != 3) { var dd = d; string nm = null; var t = new Thread(() => { nm = Q(dd, 1); }); t.Start(); if (t.Join(300)) name = nm; else name = "<name query blocked>"; } else name = "<pipe>"; }
      else if (type == "Key" || type == "Event" || type == "Mutant" || type == "Section" || type == "Semaphore") name = Q(d, 1);
      if (type == "File" || type == "Mutant" || type == "Key") res.Add(string.Format("0x{0:X} {1} ft={2} {3}", hv, type, ft, name));
