Get-Process cmd -ErrorAction SilentlyContinue | Where-Object { $_.StartTime -gt (Get-Date).AddMinutes(-3) } | Select-Object Id, StartTime, MainWindowTitle
Add-Type -TypeDefinition @'
using System; using System.Runtime.InteropServices; using System.Text;
public static class PEnv {
  [DllImport("ntdll.dll")] static extern int NtQueryInformationProcess(IntPtr h, int c, long[] info, int len, out int ret);
  [DllImport("kernel32.dll")] static extern IntPtr OpenProcess(int a, bool i, int p);
  [DllImport("kernel32.dll")] static extern bool ReadProcessMemory(IntPtr h, IntPtr a, byte[] b, IntPtr n, out IntPtr r);
  static long RdPtr(IntPtr h, long a) { var b = new byte[8]; IntPtr r; ReadProcessMemory(h, new IntPtr(a), b, new IntPtr(8), out r); return BitConverter.ToInt64(b, 0); }
  public static string Get(int pid) {
    IntPtr h = OpenProcess(0x0410, false, pid); var pbi = new long[6]; int ret;
    NtQueryInformationProcess(h, 0, pbi, 48, out ret);
    long pp = RdPtr(h, pbi[1] + 0x20); long env = RdPtr(h, pp + 0x80); long size = RdPtr(h, pp + 0x3F0);
    var b = new byte[size]; IntPtr r; ReadProcessMemory(h, new IntPtr(env), b, new IntPtr(size), out r);
    return Encoding.Unicode.GetString(b);
  }
}
'@
foreach ($p in @(Get-Process explorer) + @(Get-Process -Id 19040)) { $e = [PEnv]::Get($p.Id); $m = ($e -split "`0" | Where-Object { $_ -like 'GIT_TERMINAL_PROMPT=*' }); "{0} pid {1}: {2}" -f $p.ProcessName, $p.Id, ($(if ($m) { $m } else { '<not set>' })) }

